{
  "units": [
    {
      "quote": "The goal is the best likeness that can reasonably be obtained",
      "scope_quotes": [
        "d. Infants pose a particular challenge."
      ],
      "kind": "recommendation",
      "meaning": "For infant photographs, the guiding standard is to achieve the best likeness that can reasonably be obtained given the challenges infants pose."
    },
    {
      "quote": "It is acceptable if the infant's eyes, particularly a newborn's, are partially or completely closed",
      "scope_quotes": [
        "d. Infants pose a particular challenge. The goal is the best likeness that can reasonably be obtained:"
      ],
      "kind": "permission",
      "meaning": "In an infant photograph, especially for a newborn, having the infant's eyes partially or completely closed is officially permissible."
    },
    {
      "quote": "The infant's head may be discreetly supported, e.g., a car seat with a white or off-white blanket behind the child.",
      "scope_quotes": [
        "d. Infants pose a particular challenge. The goal is the best likeness that can reasonably be obtained:"
      ],
      "kind": "permission",
      "meaning": "The infant's head is permitted to be discreetly supported, such as in a car seat covered with a white or off-white blanket positioned behind the child."
    },
    {
      "quote": "Head tilt is acceptable for infants",
      "scope_quotes": [
        "d. Infants pose a particular challenge. The goal is the best likeness that can reasonably be obtained:"
      ],
      "kind": "permission",
      "meaning": "Head tilt is permitted and considered acceptable in photographs of infants."
    },
    {
      "quote": "A parent’s face cannot be in the photograph of the infant.",
      "scope_quotes": [
        "d. Infants pose a particular challenge. The goal is the best likeness that can reasonably be obtained:"
      ],
      "kind": "prohibition",
      "meaning": "A parent's face is strictly prohibited from appearing in the photograph of an infant."
    },
    {
      "quote": "You must request a new photograph if the photograph submitted does not meet the following requirements:",
      "scope_quotes": [],
      "kind": "requirement",
      "meaning": "The adjudicator/official must require the applicant to submit a new photograph whenever the submitted photograph fails to meet the specified photo requirements."
    },
    {
      "quote": "The photograph must be in color",
      "scope_quotes": [
        "You must request a new photograph if the photograph submitted does not meet the following requirements:"
      ],
      "kind": "requirement",
      "meaning": "The submitted passport photograph is required to be in color; non-color photographs fail requirements and necessitate a request for a new photograph."
    },
    {
      "quote": "The photograph should be taken within six months of submitting the application, be a good likeness of and satisfactorily identify the applicant at the time of the application (see 22 CFR 51.26).",
      "scope_quotes": [
        "You must request a new photograph if the photograph submitted does not meet the following requirements:"
      ],
      "kind": "recommendation",
      "meaning": "The photograph should be taken within six months prior to application submission and must serve as a good likeness that satisfactorily identifies the applicant as of the application date."
    },
    {
      "quote": "A photograph showing a change in hairstyle or facial hair from the identification document submitted is acceptable if it still is a good likeness of the applicant",
      "scope_quotes": [
        "You must request a new photograph if the photograph submitted does not meet the following requirements:"
      ],
      "kind": "permission",
      "meaning": "A photograph displaying a different hairstyle or facial hair compared to the submitted identification document is acceptable provided it remains a good likeness of the applicant."
    },
    {
      "quote": "even if the certificate itself was recently issued, because of U.S. Citizenship and Immigration Services processing times, the photograph may not have been taken within six months of submitting the application.",
      "scope_quotes": [
        "NOTE: Applicants may wish to re-use a passport photograph that is depicted on their submitted U.S Certificate of Citizenship or Certificate of Naturalization."
      ],
      "kind": "statement",
      "meaning": "Even when a Certificate of Citizenship or Naturalization was issued recently, USCIS processing times mean that the photograph appearing on it may not satisfy the requirement of being taken within six months of passport application submission."
    },
    {
      "quote": "The photograph must be free of material damage:",
      "scope_quotes": [
        "You must request a new photograph if the photograph submitted does not meet the following requirements:"
      ],
      "kind": "requirement",
      "meaning": "The submitted photograph must have no material damage; if it has material damage, a new photograph must be requested."
    },
    {
      "quote": "Material damage is any damage to the facial area that makes the photograph no longer a good likeness of the applicant (e.g., creases, large holes, and large smudges) or impedes the functioning of facial recognition (damage in the area of the eyes)",
      "scope_quotes": [
        "The photograph must be free of material damage:"
      ],
      "kind": "definition",
      "meaning": "Material damage is defined as any damage occurring in the facial area that destroys the photograph's status as a good likeness of the applicant (including creases, large holes, or large smudges) or obstructs facial recognition systems (such as damage around the eye region)."
    },
    {
      "quote": "Immaterial damage is any damage to the background, and non-material damage to the facial area (e.g., staple holes).",
      "scope_quotes": [
        "The photograph must be free of material damage:"
      ],
      "kind": "definition",
      "meaning": "Immaterial damage is defined as any damage restricted to the background of the photo, as well as non-material damage affecting the facial area (such as staple holes)."
    },
    {
      "quote": "Immaterial damage is acceptable",
      "scope_quotes": [
        "The photograph must be free of material damage:"
      ],
      "kind": "permission",
      "meaning": "A photograph possessing only immaterial damage is permissible and acceptable."
    },
    {
      "quote": "The applicant does not need to sign the photograph, as this often causes creases or smudges",
      "scope_quotes": [
        "The photograph must be free of material damage:"
      ],
      "kind": "exemption",
      "meaning": "Applicants are not required to sign their photograph, in order to avoid the risk of creating creases or smudges."
    },
    {
      "quote": "For hand-carry applications, the acceptance agent signs the back of the photograph.",
      "scope_quotes": [],
      "kind": "requirement",
      "meaning": "When handling hand-carry passport applications, the acceptance agent is required to sign the back of the photograph."
    },
    {
      "quote": "Consequently, the passport application may be returned to adjudication to request a new photograph even though the photograph appeared acceptable.",
      "scope_quotes": [
        "(d) A photograph that appears acceptable and undamaged in the system may have a defect that is apparent when the passport is printed."
      ],
      "kind": "permission",
      "meaning": "If a photograph that looked undamaged in the system reveals a defect upon passport printing, the application may be sent back to adjudication to require a replacement photograph."
    },
    {
      "quote": "Eyeglasses are not acceptable unless they cannot be removed for medical reasons, e.g., the applicant has recently had ocular surgery and the eyeglasses are necessary to protect the applicant’s eyes.",
      "scope_quotes": [
        "e. Eyeglasses/contact lenses:"
      ],
      "kind": "prohibition",
      "meaning": "Eyeglasses are strictly unacceptable in photographs, except when they cannot be taken off for documented medical justifications (such as following recent ocular surgery where glasses are essential to safeguard the eyes)."
    },
    {
      "quote": "A medical statement signed by a medical professional/health practitioner must be requested in these rare circumstances.",
      "scope_quotes": [
        "e. Eyeglasses/contact lenses:",
        "(1) Eyeglasses are not acceptable unless they cannot be removed for medical reasons, e.g., the applicant has recently had ocular surgery and the eyeglasses are necessary to protect the applicant’s eyes."
      ],
      "kind": "requirement",
      "meaning": "When an applicant cannot remove eyeglasses for medical reasons, adjudicators must require a medical statement signed by a medical professional or health practitioner."
    },
    {
      "quote": "The frames of the eyeglasses must not cover the eye(s)",
      "scope_quotes": [
        "e. Eyeglasses/contact lenses:",
        "If the eyeglasses are accepted for medical reasons:"
      ],
      "kind": "prohibition",
      "meaning": "When eyeglasses are permitted for medical reasons, the eyeglass frames are prohibited from covering any part of the applicant's eye or eyes."
    },
    {
      "quote": "There must not be glare on eyeglasses that obscures the eye(s)",
      "scope_quotes": [
        "e. Eyeglasses/contact lenses:",
        "If the eyeglasses are accepted for medical reasons:"
      ],
      "kind": "prohibition",
      "meaning": "When eyeglasses are accepted on medical grounds, there must not be any glare reflecting off the eyeglasses that obstructs or obscures the eye or eyes."
    },
    {
      "quote": "There must not be shadows or refraction from the eyeglasses that obscure the eye(s)",
      "scope_quotes": [
        "e. Eyeglasses/contact lenses:",
        "If the eyeglasses are accepted for medical reasons:"
      ],
      "kind": "prohibition",
      "meaning": "When eyeglasses are accepted for medical reasons, neither shadows nor optical refraction from the glasses may obscure the applicant's eye or eyes."
    },
    {
      "quote": "Dark or tinted lenses are permitted if the medical statement also indicates that they are required.",
      "scope_quotes": [
        "e. Eyeglasses/contact lenses:",
        "If the eyeglasses are accepted for medical reasons:"
      ],
      "kind": "permission",
      "meaning": "Dark or tinted lenses in eyeglasses are allowed only on the condition that the signed medical statement explicitly specifies that they are medically required."
    }
  ]
}
